                        cr, cc = stack.pop()
                        if (cr, cc) not in visited and grid[cr][cc] == color:
                            visited.add((cr, cc))
                            cells.append((cr, cc))
                            bbox['min_r'] = min(bbox['min_r'], cr)
                            bbox['max_r'] = max(bbox['max_r'], cr)
                            bbox['min_c'] = min(bbox['min_c'], cc)
                            bbox['max_c'] = max(bbox['max_c'], cc)
                            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                                nr, nc = cr + dr, cc + dc
                                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                    stack.append((nr, nc))
                    shapes[color] = {'cells': cells, 'bbox': bbox}
        return shapes

    shapes_in = find_shapes_and_offsets(grid)

    # Compute offset for each shape
    all_min_rows = [shape_info['bbox']['min_r'] for shape_info in shapes_in.values()]
