    max_h = max(shape_info['bbox']['max_r'] for shape_info in shapes_in.values())
    num_rows = max_h - target_min_row + 1

    new_grid = [[0] * len(grid[0]) for _ in range(num_rows)]

    for color, info in shapes_in.items():
        offset = target_min_row - info['bbox']['min_r']
        for r, c in info['cells']:
