    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                stack = [(r, c)]
                cells = []
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) not in visited and grid[cr][cc] == color:
                        visited.add((cr, cc))
                        cells.append((cr, cc))
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                stack.append((nr, nc))
                min_r = min(cell[0] for cell in cells)
                min_c = min(cell[1] for cell in cells)
                max_r = max(cell[0] for cell in cells)
                max_c = max(cell[1] for cell in cells)
                shapes.append((color, min_r, min_c, max_r, max_c, cells))
    return sorted(shapes, key=lambda x: x[1])

