        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                bbox = {'min_r': r, 'max_r': r, 'min_c': c, 'max_c': c}
                stack = [(r, c)]
                cells = []

                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) not in visited and grid[cr][cc] == color:
                        visited.add((cr, cc))
                        cells.append((cr, cc))
                        bbox['min_r'] = min(bbox['min_r'], cr)
                        bbox['max_r'] = max(bbox['max_r'], cr)
                        bbox['min_c'] = min(bbox['min_c'], cc)
                        bbox['max_c'] = max(bbox['max_c'], cc)

                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                stack.append((nr, nc))

                shapes[color] = {'cells': cells, 'bbox': bbox}

    print("Shapes found:")
    for color, info in sorted(shapes.items()):
        offset = 1 - info['bbox']['min_r']
        print(f"  {color}: min_row={info['bbox']['min_r']}, offset={offset}")

    # Step 2: Build output grid with preserved dimensions
    num_rows = len(grid)
    num_cols = len(grid[0])
    output = [[0] * num_cols for _ in range(num_rows)]

    for color, info in shapes.items():
        offset = 1 - info['bbox']['min_r']
        for r, c in info['cells']:
            new_r = r + offset
